def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= 700:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgent = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
        if supply >= 22:
            target = max(DAILY_SALARY * 0.82, avg_prev + 2.0)
        return float(min(budget, target))

    if supply >= 23:
        if highest_prev >= DAILY_SALARY * 1.4:
            target = DAILY_SALARY * 0.42
        else:
            target = max(DAILY_SALARY * 0.48, avg_prev * 0.78 + 1.0)
        if pressured:
            target = max(target, DAILY_SALARY * 0.62)
        return float(min(budget, target))

    if supply <= 17:
        if highest_prev >= DAILY_SALARY * 1.2 and hp >= 6 and no_water == 0:
            return float(min(budget, DAILY_SALARY * 0.18))
        target = max(DAILY_SALARY * 0.72, highest_prev + 2.5)
        if rich_count >= 2:
            target += 6.0
        if pressured:
            target = max(target, DAILY_SALARY * 0.88)
        return float(min(budget, target))

    target = DAILY_SALARY * (0.52 + (1.0 - scarcity) * 0.18)
    if highest_prev > 0:
        target = max(target, min(highest_prev + 1.5, DAILY_SALARY * 0.92))
    if highest_prev >= DAILY_SALARY * 1.25 and hp >= 7 and no_water == 0:
        target = DAILY_SALARY * 0.28
    if desperate_count >= 2:
        target += 5.0
    if pressured:
        target = max(target, DAILY_SALARY * 0.74)
    if day >= 8 and hp <= 5:
        target = max(target, DAILY_SALARY * 0.84)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    current_bid = DAILY_SALARY * 0.65

    if my_status['hp'] <= WATER_REQ:
        current_bid = DAILY_SALARY * 1.25
    elif my_status['hp'] <= WATER_REQ * 2:
        current_bid = DAILY_SALARY * 1.0
    elif my_status['no_water_days'] > 0:
        current_bid = DAILY_SALARY * 0.9

    if day_context['supply'] < 20:
        current_bid *= 1.1
    elif day_context['supply'] > 20:
        current_bid *= 0.9

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid >= DAILY_SALARY * 0.8:
            current_bid = max(current_bid, max_yesterday_bid + 2)
        elif avg_yesterday_bid >= DAILY_SALARY * 0.7:
            current_bid = max(current_bid, avg_yesterday_bid + 1)

    num_full_water_slots = int(day_context['supply'] // WATER_REQ)

    if (num_alive_opponents + 1) > num_full_water_slots:
        current_bid *= 1.1
    else:
        current_bid *= 0.95

    current_bid = min(current_bid, my_status['budget'])
    current_bid = max(1.0, current_bid)

    return current_bid
